"""Alignment of NMF components with ground-truth pitches.

NMF recovers templates ``W`` of shape ``(F, n_components)`` and activations
``H`` in arbitrary order and scale. This module builds a reference spectral
template for each pitch from frames where only that pitch sounds, matches NMF
components to pitches by cosine similarity with the Hungarian algorithm, and
estimates per-pitch activation scales so ``H`` can be compared to the binary
note activity ``Y``.
"""

import numpy as np
from scipy.optimize import linear_sum_assignment


# Generated by Claude Code
def reference_templates(V, Y):
    """Build a reference spectral template for each pitch.

    For each pitch ``k``, the template is the mean spectrum over the set
    ``T_k`` of frames where pitch ``k`` is the only active pitch, normalized
    to sum to one.

    Parameters
    ----------
    V : array_like, shape (F, T)
        Non-negative magnitude spectrogram.
    Y : array_like, shape (K, T)
        Note activity; non-zero entries are treated as active.

    Returns
    -------
    dict
        ``"R"`` : ndarray, shape (F, K) -- reference templates, each column
        summing to one.
        ``"n_frames"`` : ndarray of int, shape (K,) -- number of single-pitch
        frames ``|T_k|`` used for each template.

    Raises
    ------
    ValueError
        If ``V`` or ``Y`` is not 2-D, they differ in number of frames, or some
        pitch has no frames where it sounds alone.
    """
    V = np.asarray(V, dtype=float)
    Y = np.asarray(Y)
    if V.ndim != 2 or Y.ndim != 2 or Y.shape[1] != V.shape[1]:
        raise ValueError("V and Y must share the time axis")

    Yb = Y.astype(bool)
    only_one = Yb.sum(axis=0) == 1  # frames where exactly one pitch is active
    F, K = V.shape[0], Yb.shape[0]

    R = np.empty((F, K))
    n_frames = np.empty(K, dtype=int)

    for k in range(K):
        mask = Yb[k] & only_one
        n_frames[k] = int(mask.sum())
        if n_frames[k] == 0:
            raise ValueError(f"no single-pitch frames for pitch {k}")
        v_bar = V[:, mask].mean(axis=1)  # mean spectrum over T_k
        R[:, k] = v_bar / v_bar.sum()  # normalize to sum one

    return {
        "R": R,
        "n_frames": n_frames
    }


def cosine_similarity(A, B, eps=1e-12):
    """Compute pairwise cosine similarity between the columns of two matrices.

    Parameters
    ----------
    A : array_like, shape (F, M)
        First set of column vectors.
    B : array_like, shape (F, N)
        Second set of column vectors.
    eps : float, optional
        Floor applied to column norms to avoid division by zero; all-zero
        columns get similarity 0 with everything.

    Returns
    -------
    ndarray, shape (M, N)
        Entry ``(i, j)`` is the cosine similarity between ``A[:, i]`` and
        ``B[:, j]``.
    """
    A = np.asarray(A, float)
    B = np.asarray(B, float)

    An = A / np.maximum(np.linalg.norm(A, axis=0, keepdims=True), eps)
    Bn = B / np.maximum(np.linalg.norm(B, axis=0, keepdims=True), eps)

    return An.T @ Bn  # (A.shape[1], B.shape[1])


def match_components(W, R):
    """Assign one NMF component to each pitch by maximum cosine similarity.

    Solves the linear assignment problem on the component-by-pitch similarity
    matrix (Hungarian algorithm), maximizing the total similarity so that each
    pitch gets a distinct component.

    Parameters
    ----------
    W : array_like, shape (F, n_components)
        NMF templates, with ``n_components >= K``.
    R : array_like, shape (F, K)
        Reference templates, e.g. from :func:`reference_templates`.

    Returns
    -------
    dict
        ``"perm"`` : ndarray of int, shape (K,) -- ``perm[k]`` is the index of
        the component assigned to pitch ``k``, so ``W[:, perm]`` and
        ``H[perm]`` are in pitch order.
        ``"similarity"`` : ndarray, shape (n_components, K) -- full cosine
        similarity matrix.
        ``"matched"`` : ndarray, shape (K,) -- similarity of each pitch to its
        assigned component.
        ``"unmatched"`` : list of int -- indices of components not assigned to
        any pitch.

    Raises
    ------
    ValueError
        If ``W`` has fewer columns than ``R``.
    """
    W = np.asarray(W, dtype=float)
    R = np.asarray(R, dtype=float)
    if W.shape[1] < R.shape[1]:
        raise ValueError(
            f"need at least as many components as pitches "
            f"(got {W.shape[1]} components for {R.shape[1]} pitches)")

    S = cosine_similarity(W, R)

    rows, cols = linear_sum_assignment(S, maximize=True)

    perm = np.empty(R.shape[1], dtype=int)
    perm[cols] = rows  # perm[k] = component assigned to pitch k

    matched = S[perm, np.arange(R.shape[1])]
    used = set(perm.tolist())
    unmatched = [j for j in range(S.shape[0]) if j not in used]

    return {
        "perm": perm,
        "similarity": S,
        "matched": matched,
        "unmatched": unmatched
    }


def activation_scales(H, Y, q=95.0):
    """Estimate a scale for each row of the activations.

    The scale of pitch ``k`` is the ``q``-th percentile of ``H[k]`` over the
    frames where pitch ``k`` is active, so ``H / c[:, None]`` is roughly in
    ``[0, 1]`` and comparable to ``Y``.

    Parameters
    ----------
    H : array_like, shape (K, T)
        Activations, already in pitch order (e.g. ``H[perm]`` from
        :func:`match_components`).
    Y : array_like, shape (K, T)
        Note activity; non-zero entries are treated as active.
    q : float, optional
        Percentile in ``[0, 100]``.

    Returns
    -------
    ndarray, shape (K,)
        Scale per pitch, floored at ``1e-12``.

    Raises
    ------
    ValueError
        If ``H`` and ``Y`` differ in shape, or some pitch is never active.
    """
    H = np.asarray(H, dtype=float)
    Y = np.asarray(Y).astype(bool)

    if H.shape != Y.shape:
        raise ValueError("H and Y must have the same shape (K, T)")

    K = H.shape[0]
    c = np.empty(K)

    for k in range(K):
        active = H[k, Y[k]]
        if active.size == 0:
            raise ValueError(f"pitch {k} is never active")
        c[k] = np.percentile(active, q)

    return np.maximum(c, 1e-12)
